import java.util.Scanner;

public class TelephoneBill {
    private String name;
    private int callCount;
    private double bill;

    public TelephoneBill() {
        name = "";
        callCount = 0;
        bill = 0.0;
    }

    public void input() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Customer Name: ");
        name = in.nextLine();
        System.out.print("Enter Number of Calls: ");
        callCount = in.nextInt();
    }

    public void calculate() {
        double rental = 250.0;
        double callCharges = 0.0;

        if (callCount <= 100) {
            callCharges = 0.0;
        } else if (callCount <= 200) {
            callCharges = (callCount - 100) * 1.20;
        } else if (callCount <= 300) {
            callCharges = (100 * 1.20) + (callCount - 200) * 1.50;
        } else {
            callCharges = (100 * 1.20) + (100 * 1.50) + (callCount - 300) * 2.00;
        }

        double gst = 0.18 * callCharges;
        bill = rental + callCharges + gst;
    }

    public void display() {
        System.out.println("\n============== TELEPHONE BILL ==============");
        System.out.println("Customer Name       : " + name);
        System.out.println("Calls Made          : " + callCount);
        System.out.println("Monthly Rental      : Rs. 250.00");
        System.out.println("Total Amount Payable: Rs. " + bill);
        System.out.println("============================================");
    }

    public static void main(String[] args) {
        TelephoneBill tb = new TelephoneBill();
        tb.input();
        tb.calculate();
        tb.display();
    }
}
```

