import java.util.Scanner;

public class SecondMinMaxFinder {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 15;
        int[] arr = new int[N];

        System.out.println("Enter " + N + " distinct integers:");
        for (int i = 0; i < N; i++) {
            arr[i] = sc.nextInt();
        }

        int max = Integer.MIN_VALUE, secondMax = Integer.MIN_VALUE;
        int min = Integer.MAX_VALUE, secondMin = Integer.MAX_VALUE;

        for (int i = 0; i < N; i++) {
            int val = arr[i];

            // Update max and second max
            if (val > max) {
                secondMax = max;
                max = val;
            } else if (val > secondMax && val != max) {
                secondMax = val;
            }

            // Update min and second min
            if (val < min) {
                secondMin = min;
                min = val;
            } else if (val < secondMin && val != min) {
                secondMin = val;
            }
        }

        System.out.println("\nLargest Element        : " + max);
        System.out.println("Second Largest Element : " + secondMax);
        System.out.println("Smallest Element       : " + min);
        System.out.println("Second Smallest Element: " + secondMin);
    }
}
```

