import java.util.Scanner;

public class LongestWordFinder {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter a sentence terminating with '.':");
        String s = in.nextLine().trim();

        if (s.endsWith(".")) {
            s = s.substring(0, s.length() - 1).trim();
        }

        s = s + " "; // Trailing space for word extraction
        String currentWord = "";
        String longestWord = "";

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            if (ch != ' ') {
                currentWord += ch;
            } else {
                if (currentWord.length() > longestWord.length()) {
                    longestWord = currentWord;
                }
                currentWord = "";
            }
        }

        System.out.println("\nSentence without delimiter: " + s.trim());
        System.out.println("Longest Word              : " + longestWord);
        System.out.println("Length of Longest Word    : " + longestWord.length() + " characters");
    }
}
```

