import java.util.Scanner;

public class PronicNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        int n = sc.nextInt();

        if (n < 0) {
            System.out.println("Negative numbers cannot be Pronic numbers.");
            return;
        }

        boolean isPronic = false;
        int kVal = -1;

        for (int k = 0; k * (k + 1) <= n; k++) {
            if (k * (k + 1) == n) {
                isPronic = true;
                kVal = k;
                break;
            }
        }

        System.out.println();
        if (isPronic) {
            System.out.println(n + " is a PRONIC NUMBER (" + kVal + " x " + (kVal + 1) + " = " + n + ").");
        } else {
            System.out.println(n + " is NOT a Pronic Number.");
        }
    }
}
```

