import java.util.Scanner;

public class MatrixRowColSums {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        final int R = 4, C = 4;
        int[][] mat = new int[R][C];

        System.out.println("Enter elements for 4x4 matrix:");
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                mat[i][j] = in.nextInt();
            }
        }

        System.out.println("\nMatrix Representation:");
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                System.out.printf("%5d", mat[i][j]);
            }
            System.out.println();
        }

        System.out.println("\nRow Sums:");
        for (int i = 0; i < R; i++) {
            int rowSum = 0;
            for (int j = 0; j < C; j++) {
                rowSum += mat[i][j];
            }
            System.out.println("Row " + (i + 1) + " Sum = " + rowSum);
        }

        System.out.println("\nColumn Sums:");
        for (int j = 0; j < C; j++) {
            int colSum = 0;
            for (int i = 0; i < R; i++) {
                colSum += mat[i][j];
            }
            System.out.println("Column " + (j + 1) + " Sum = " + colSum);
        }
    }
}
```

