public class OverloadVolume {
    public double volume(double s) {
        return Math.pow(s, 3);
    }

    public double volume(double r, double h) {
        return Math.PI * r * r * h;
    }

    public double volume(double l, double b, double h) {
        return l * b * h;
    }

    public static void main(String[] args) {
        OverloadVolume calc = new OverloadVolume();

        double cubeVol = calc.volume(5.0);
        System.out.printf("Volume of Cube (side 5.0)              = %.2f cu. units\n", cubeVol);

        double cylVol = calc.volume(3.5, 10.0);
        System.out.printf("Volume of Cylinder (r=3.5, h=10.0)      = %.2f cu. units\n", cylVol);

        double cuboidVol = calc.volume(6.0, 4.0, 3.0);
        System.out.printf("Volume of Cuboid (6.0 x 4.0 x 3.0)       = %.2f cu. units\n", cuboidVol);
    }
}
```

